        if (/\/(nunito-sans|fredoka)-.*\.woff2$/.test(item.fileName))
          initial.add("./" + item.fileName);
      }
      const version = createHash("sha256")
        .update(JSON.stringify(Object.keys(bundle)))
        .digest("hex")
