                p,
                e.x,
                e.y,
                e.kind === 5 ? 25 : 17,
                e.kind === 5 ? 17 : 13,
              );
              if (t < nearest) {
                nearest = t;
                target = e;
              }
            }
          if (!target) break;
          p.hits.push(target);
          p.pierce--;
          if (p.pierce <= 0) p.active = false;
          target.hp -= p.damage;
          target.hit = 0.09;
          this.effect(target.x, target.y, "hit");
          if (target.hp <= 0) {
            target.alive = false;
            this.kills++;
            this.score += 10 + target.kind * 5;
            this.drop(target);
