        this.player.x = 210;
      }
    } else if (!this.enemies.some((e) => e.alive)) {
      this.score += this.wave * 50;
      this.nextWave = 1.15;
      this.projectiles.forEach((p) => (p.active = false));
    }
  }

get transitioning() {
    return this.nextWave > 0;
  }

