  resume() {
    this.enabled = true;
    this.clear();
  }
  dispose() {
    this.pause();
    this.cleanups.splice(0).forEach((fn) => fn());
    this.clearHandlers = [];
  }
  get listenerCount() {
    return this.cleanups.length;
  }
}

