constructor(
    private difficulty: Difficulty,
    seed?: number,
  ) {
    this.personality = new MatchRandom(seed);
  }

update(m: ArcheryMatch) {
    if (m.winner) return false;
    const p = m.players[1],
      r = this.personality;
    if (this.attempt !== p.attempt) {
      this.attempt = p.attempt;
      const target =
          p.targets[
            this.difficulty === "impossible" ||
