        .beginPath()
        .arc(m.x, m.y - 2, 8, 3.5, 5)
        .strokePath();
    });
    g.fillStyle(theme.ink, 0.12).fillCircle(w.puck.x, w.puck.y + 4, 12);
    circle(g, w.puck.x, w.puck.y, 11, theme.ink, 0);
    g.fillStyle(0x5b6770).fillCircle(w.puck.x - 2, w.puck.y - 3, 4);
    this.effects.draw(g, dt);
    this.status.setText(
      w.cooldown > 0.5
        ? this.violation
          ? "POSSESSION!"
          : "READY?"
        : w.cooldown > 0
          ? "GO!"
          : "",
    );
  }

private save() {
    if (!this.world.done)
      this.ctx.saveState({
        ...saveHockey(this.world, this.matchClock, this.possession),
        ai: this.ai?.snapshot(),
      });
  }

private malletTarget(player: 0 | 1, step: number): Vec {
    const pointer = this.ctx.input.players[player];
    if (pointer.down) return pointer;
    const arrows = player === 1 || !!this.ai;
    const up =
      (player === 0 && this.keys.has("KeyW")) ||
      (arrows && this.keys.has("ArrowUp"));
    const down =
      (player === 0 && this.keys.has("KeyS")) ||
      (arrows && this.keys.has("ArrowDown"));
    const left =
      (player === 0 && this.keys.has("KeyA")) ||
      (arrows && this.keys.has("ArrowLeft"));
    const right =
      (player === 0 && this.keys.has("KeyD")) ||
      (arrows && this.keys.has("ArrowRight"));
    let vx = Number(right) - Number(left);
    let vy = Number(down) - Number(up);
    const m = this.world.mallets[player];
    if (vx === 0 && vy === 0) return m;
    const len = Math.hypot(vx, vy);
    vx /= len;
    vy /= len;
    const puckSpeed = Math.hypot(this.world.puck.vx, this.world.puck.vy);
    const speed = Math.min(1350, Math.max(950, puckSpeed * 1.25));
    return {
      x: m.x + vx * speed * step,
      y: m.y + vy * speed * step,
    };
  }

pause() {
    this.save();
    this.paused = true;
    this.clock.reset();
  }

resume() {
    this.paused = false;
    this.clock.reset();
  }

dispose() {
    this.bg.destroy();
    this.graphics.destroy();
    this.status.destroy();
    this.possessionLabel.destroy();
  }

snapshot() {
    return {
      ai: this.ai?.snapshot(),
      possession: {
        side: this.possession.side,
        remaining: this.possession.remaining,
      },
      puck: { ...this.world.puck },
      mallets: this.world.mallets.map((m) => ({ ...m })),
      timer: {
        remaining: this.matchClock.remaining,
        overtime: this.matchClock.overtime,
      },
      scores: [...this.world.scores],
    };
  }

