    const next = y > 384 ? 1 : y < 378 ? 2 : this.side;
    if (next !== this.side) {
      this.side = next;
      this.elapsed = 0;
    }
    if (this.side === null) return null;
    this.elapsed += dt;
    if (this.elapsed < 15) return null;
    const opponent = this.side === 1 ? 2 : 1;
    this.reset();
    return opponent;
  }

