  if (y < FIELD.top + r - 0.01 || y > FIELD.bottom - r + 0.01) return false;
  const cx = clamp(x, FIELD.left + CORNER, FIELD.right - CORNER),
    cy = clamp(y, FIELD.top + CORNER, FIELD.bottom - CORNER);
