        .run({
          state: this.board.save(),
          difficulty: this.ctx.options.difficulty,
          seed: this.personality.seed,
          replay: replayMode(),
        })
        .then((r) => {
          if (token !== this.generation) return;
          this.pending = false;
          this.place(r?.edge ?? this.board.legal()[0], true);
        });
    }
    const g = this.g;
    g.clear();
