      // Recognition errors are sampled once per presented fruit, never per frame.
      this.mistake =
        style.next() <
        { medium: 0.1, hard: 0.02, impossible: 0 }[this.difficulty] *
          (cautious ? 0.6 : style.role === 0 ? 1.3 : 1);
