      oval(0, 0, 38, 38, 0xffe7a2);
      const p = Array.from({ length: 10 }, (_, i) => ({
        x: Math.sin((i * Math.PI) / 5) * (i % 2 ? 8 : 16),
        y: -Math.cos((i * Math.PI) / 5) * (i % 2 ? 8 : 16),
