    g.translateCanvas(p.x, p.y);
    g.scaleCanvas(p.face, 1);
    g.rotateCanvas(p.angle);
    g.scaleCanvas(1 - 0.12 * p.bump, 1 + 0.08 * p.bump);
    // Broad, rounded silhouettes echo the original menu illustration.
