    g.rotateCanvas(-0.3 - wing * 1.25);
    g.fillStyle(recoveryColor(0xfff8df, tint)).fillEllipse(-5, 2, 19, 12);
    g.lineStyle(1.7, theme.ink).strokeEllipse(-5, 2, 19, 12);
    g.restore();
    g.restore();
    if (!p.alive) {
