      this.trailAge %= 0.045;
      for (let i = 0; i < 2; i++) {
        for (let j = 5; j > 0; j--)
          Object.assign(this.trails[i][j], this.trails[i][j - 1]);
        Object.assign(this.trails[i][0], result[i]);
      }
    }
    return result;
  }

