export interface StarBurst {
  x: number;
  y: number;
  player: 0 | 1;
  age: number;
}
/** Uniform candidates across the open arena; reject instant pickups and nearby repeats. */
export function spawnStar(
  random: MatchRandom,
  id: number,
  age: number,
  players: readonly Bird[],
  previous?: { x: number; y: number },
): Star {
