  }
  dispose() {
    this.g.destroy();
    this.text.destroy();
  }
  snapshot() {
    return {
      ai: this.ai?.snapshot(),
      phase: this.m.phase,
      round: this.m.round,
      players: this.m.players.map((p) => ({ ...p })),
      pattern: [...this.m.pattern.slice(0, 40)],
      totals: [...this.m.totals],
      time: this.m.time,
      winner: this.m.winner,
    };
  }
