export type Side=-1|1;
export const ROUND_SECONDS=20;
export function branches(seed:number,count=600){let s=seed>>>0,last=0;return Array.from({length:count},(_,i)=>{s=(Math.imul(s,1664525)+1013904223)>>>0;const value=i<2||last!==0?0:s%3-1;last=value;return value;});}
export class LumberMatch {
 pattern:number[];players=[{score:0,side:-1 as Side,alive:true,idle:0,cooldown:0},{score:0,side:1 as Side,alive:true,idle:0,cooldown:0}];totals:[number,number]=[0,0];round=1;phase:'playing'|'between'|'done'='playing';time=0;between=0;winner:1|2|null=null;
 constructor(readonly seed=12345){this.pattern=branches(seed);}
 limit(p:number){return Math.max(.32,1.5-this.players[p].score*.035);}
 safe(p:number,side:Side){const index=this.players[p].score;return this.pattern[index]!==side&&this.pattern[index+1]!==side;}
 chop(p:0|1,side:Side){const v=this.players[p];if(this.phase!=='playing'||!v.alive||v.cooldown>0)return null;v.side=side;v.cooldown=.085;if(!this.safe(p,side)){v.alive=false;return false;}v.score++;v.idle=0;return true;}
 update(dt:number){if(this.phase==='done')return;if(this.phase==='between'){this.between-=dt;if(this.between<=0){this.round++;this.time=0;this.pattern=branches(this.seed+this.round*7919);this.players.forEach(p=>{p.score=0;p.alive=true;p.idle=0;p.cooldown=0;});this.phase='playing';}return;}this.time+=dt;for(const p of this.players){p.cooldown=Math.max(0,p.cooldown-dt);if(p.alive){p.idle+=dt;if(p.idle>Math.max(.32,1.5-p.score*.035))p.alive=false;}}if(this.time>=ROUND_SECONDS)this.players.forEach(p=>p.alive=false);if(this.players.every(p=>!p.alive)){this.players.forEach((p,i)=>this.totals[i]+=p.score);if(this.round>=3&&this.totals[0]!==this.totals[1]){this.winner=this.totals[0]>this.totals[1]?1:2;this.phase='done';}else{this.phase='between';this.between=1.4;}}}
}

import type {Difficulty} from '../../shared/contracts/AIController';import type {QuizMatch} from './Rules';
/** Bank-answer selection with calibrated timing, explicitly not symbolic reasoning. */
export class QuizAI {private id='';private tapped=false;private delay=1;private answer=0;constructor(private difficulty:Difficulty,private random=Math.random){}update(m:QuizMatch){if(m.question.id!==this.id){this.id=m.question.id;this.tapped=false;const q=m.question;this.delay=Math.max(.6,q.estimatedSeconds*{medium:.8,hard:.48,impossible:.25}[this.difficulty])*(.9+this.random()*.2);const accuracy={medium:.72,hard:.93,impossible:1}[this.difficulty];this.answer=this.random()<accuracy?q.correctIndex:(q.correctIndex+1+Math.floor(this.random()*2))%3;}if(!this.tapped&&m.phase==='active'&&m.time-m.visibleAt>=this.delay){m.answer(1,this.answer);this.tapped=true;}}}

import type {GameContext,MiniGame} from '../../shared/contracts/GameModule';import {QuizMatch} from './Rules';import {QuizAI} from './AI';import {MathUI} from './MathUI';import {basicQuestion} from './questions/Basic';import {universityDeck} from './questions/Bank';import {globalQuestionHistory} from './questions/History';
export class MathGame implements MiniGame {
 private ctx!:GameContext;private m!:QuizMatch;private ai?:QuizAI;private ui!:MathUI;private paused=false;private round=0;private finished=0;private reported=false;
 initialize(ctx:GameContext){this.ctx=ctx;let serial=0,deck=universityDeck(),last='';const next=()=>{let q;if(ctx.options.variant!=='university')q=basicQuestion(serial++);else{if(!deck.length){deck=universityDeck();if(deck[0].id===last)deck.push(deck.shift()!);}q=deck.shift()!;}last=q.id;globalQuestionHistory.record(q.id);return q;};this.m=new QuizMatch(next);if(ctx.options.mode==='ai')this.ai=new QuizAI(ctx.options.difficulty);this.ui=new MathUI(!this.ai,(p,i)=>{if(!this.paused&&!(p===1&&this.ai))this.m.answer(p,i);});ctx.input.press(['Digit1','Digit2','Digit3','Digit7','Digit8','Digit9'],code=>{const n=Number(code.at(-1));if(!this.paused&&!(n>=7&&this.ai))this.m.answer(n>=7?1:0,n>=7?n-7:n-1);});ctx.setScore(0,0);ctx.setHint('SAME QUESTION. THREE ANSWERS. ONE QUICK MIND.');ctx.audio.play('start');this.ui.render(this.m,!!this.ai);this.m.present();}
 update(dt:number){if(this.paused)return;this.m.update(dt);this.ai?.update(this.m);if(this.round!==this.m.round){this.round=this.m.round;this.ctx.setScore(...this.m.scores);this.ctx.audio.play(this.m.message==='CORRECT!'?'capture':'fail');}this.ui.render(this.m,!!this.ai);this.m.present();if(this.m.winner){this.finished+=dt;if(this.finished>1.4&&!this.reported){this.reported=true;this.ctx.finish({winner:this.m.winner,scores:this.m.scores});}}}
 resize(){this.ui?.resize();}pause(){this.paused=true;this.ui.pause(true);}resume(){this.paused=false;this.ui.pause(false);this.resize();}dispose(){this.ui.dispose();}snapshot(){return {phase:this.m.phase,question:this.m.question,scores:[...this.m.scores],round:this.m.round,time:this.m.time,winner:this.m.winner};}
}

