    this.root.style.top = `${canvasRect.y - stageRect.y}px`;
    this.root.style.transform = `scale(${canvasRect.width / 420})`;
    this.fit();
  }

pause(p: boolean) {
    this.root.hidden = p;
  }

dispose() {
    this.root.remove();
  }

