    x: dx * co + dy * si,
    y: -dx * si + dy * co,
    vx: 0,
    vy: 0,
  };
  const before = { x: local.x, y: local.y };
  hitRect(local, { x: -w / 2, y: -h / 2, w, h });
  if (local.x === before.x && local.y === before.y) return false;
  const nx = local.x - before.x,
    ny = local.y - before.y,
