    if (window.time === 0) {
      window.x = b.x;
      window.y = b.y;
      window.impacts = this.impacts;
      window.range = 0;
    }
    window.time += dt;
    window.range = Math.max(
      window.range,
      Math.hypot(b.x - window.x, b.y - window.y),
    );
    if (window.time >= 8) {
      if (
        !this.stopped &&
        window.range < 55 &&
        this.impacts - window.impacts > 24
      ) {
        this.recover("Trapped ball recovered");
        window.time = 0;
        return;
      }
      window.time = 0;
    }
    if (
      !Number.isFinite(b.x + b.y + b.vx + b.vy) ||
      b.x < -100 ||
      b.x > 2020 ||
      b.y < -100 ||
      b.y > 1180
    ) {
      this.recover("Ball recovered");
      return;
    }
    if (Math.abs(b.x - c.hole.x) < 8.25 && Math.abs(b.y - c.hole.y) < 8.25) {
      Object.assign(b, c.hole, { vx: 0, vy: 0 });
      this.status = "won";
    } else if (this.strokes >= this.limit && this.stopped) this.status = "lost";
  }

