    const d = this.dynamics;
    return {
      course: this.course.id,
      difficulty: this.difficulty,
      seed: this.seed,
      ball: { ...this.ball },
      lastShot: { ...this.lastShot },
      strokes: this.strokes,
      status: this.status,
      dynamics: {
