    if (ci === 3) {
      if (Math.hypot(tx - 1810, ty - 200) < 60 && !trial.dynamics.plates[1])
        cost += 200;
      if (Math.hypot(tx - 1810, ty - 950) < 60 && !trial.dynamics.plates[2])
        cost += 200;
