.golf-ui button:disabled {
  opacity: 0.5;
  cursor: default;
}
.golf-ui button:focus-visible {
  outline: 3px solid #58addb;
  outline-offset: 2px;
}
.golf-header {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  flex-shrink: 0;
}
.golf-heading {
  flex: 1;
  min-width: 0;
  line-height: 1.15;
}
.golf-heading strong {
  font: 600 clamp(17px, 3vw, 22px) "Fredoka";
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.golf-heading small {
  display: block;
  font-size: 13px;
  margin-top: 3px;
  font-weight: 700;
}
.golf-icon-button {
  width: 48px;
  padding: 6px !important;
  flex-shrink: 0;
}
.golf-field {
  flex: 1;
  min-height: 0;
  position: relative;
}
.golf-footer {
  display: flex;
  justify-content: center;
  gap: 10px;
  flex-shrink: 0;
  padding-top: 2px;
}
.golf-footer button {
  flex: 1;
  max-width: 220px;
}
