@media (min-width: 720px) {
  .golf-modes {
    grid-template-columns: repeat(3, 1fr);
  }
  .golf-mode {
    flex-direction: column;
    text-align: center;
    justify-content: center;
  }
  .golf-mode svg {
    width: 100px;
  }
  .golf-panel {
    gap: 20px;
  }
  .golf-header {
    max-width: 1200px;
    width: 100%;
    margin: auto;
  }
}
@media (max-height: 480px) {
  .golf-ui {
    padding: 5px 12px 8px;
    gap: 8px;
  }
  .golf-panel {
    padding: 10px;
    gap: 10px;
  }
  .golf-mode {
    min-height: 130px !important;
