    gap: 6px;
  }
  .golf-mode svg {
    width: 60px;
  }
  .golf-mode strong {
    font-size: 18px;
  }
  .golf-mode small {
    font-size: 12px;
  }
  .golf-course {
    min-height: 58px !important;
  }
  .golf-courses {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .golf-heading small {
    font-size: 12px;
  }
}
@media (prefers-reduced-motion: no-preference) {
  .golf-mode {
    transition: transform 0.12s ease;
  }
  .golf-mode:hover {
    transform: translateY(-2px);
  }
}

