score(scores: readonly number[]) {
    if (this.winner !== null) return this.winner;
    if (scores[0] >= 5 || scores[1] >= 5)
      this.winner = scores[0] > scores[1] ? 1 : 2;
    else if (this.overtime && scores[0] !== scores[1])
      this.winner = scores[0] > scores[1] ? 1 : 2;
    return this.winner;
