    this.remaining -= Math.max(0, dt);
    if (this.remaining <= 0) {
      if (scores[0] !== scores[1]) this.winner = scores[0] > scores[1] ? 1 : 2;
      else if (!this.overtime && scores[0] > 0) {
        this.overtime = true;
        this.remaining += 60;
        if (this.remaining <= 0) this.winner = "draw";
      } else this.winner = "draw";
