}
.collection-modes button {
  font-size: 12px;
  min-height: 44px;
}
.collection-modes {
  gap: 5px;
}
.arcade-dock {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 26px;
  gap: 16px;
}
.arcade-dock strong {
  font-family: Fredoka;
  font-size: 20px;
}
.arcade-dock small {
  color: #697474;
}
.diagnostics {
  position: fixed;
  top: 8px;
  left: 8px;
  max-width: 320px;
  white-space: pre-wrap;
  z-index: 100;
  pointer-events: none;
  font: 10px/1.4 monospace;
  background: #242b32e8;
  color: #fff9ee;
  border-radius: 8px;
  padding: 10px;
}
.arcade-result-score {
  font: 700 80px Fredoka;
  color: #58addb;
  margin: 10px;
}

/* Winner-colored celebration, retaining the existing brief modal entrance. */
.result-modal:has(.result-emblem.orange) { background: #f7e1cc; }
.result-modal:has(.result-emblem.blue) { background: #d9eaf4; }
.result-modal:has(.result-emblem.orange) .result-emblem { box-shadow: 0 0 0 12px #f5a05a55, 4px 5px 0 var(--ink); }
.result-modal:has(.result-emblem.blue) .result-emblem { box-shadow: 0 0 0 12px #58add555, 4px 5px 0 var(--ink); }

/* Metadata map thumbnails use the same picker component at a readable size. */
.variant-choices:has(.map-preview) {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin: 14px 0;
}
.variant-choice:has(.map-preview) { min-width: 0; padding: 9px; }
.variant-choice:has(.map-preview) b { font-size: 14px; }
.variant-choice:has(.map-preview) small { font-size: 10px; }
.variant-preview-icon .map-preview { width: 72px; height: 72px; }

