async function tapGame(page: Page, x: number, y: number) {
  const box = await page.locator("canvas").boundingBox();
  if (!box) throw Error("No canvas");
  await page.touchscreen.tap(
    box.x + (x / 420) * box.width,
    box.y + (y / 760) * box.height,
  );
}

