  page,
}) => {
  await page.goto("/");
  await page
    .getByRole("button", { name: "Play Hammer Hit", exact: true })
    .click();
  await page.getByRole("radio", { name: /2 Players/ }).click();
  await page.getByRole("button", { name: /Let’s play/ }).click();
  await expect
    .poll(async () => (await state(page)).scene.game?.cooldowns[0])
    .toBe(0);
