function clone(w: GolfPhysics) {
  const n = new GolfPhysics(w.course, w.difficulty, () => 0.9);
  Object.assign(n.ball, w.ball);
  n.lastShot = { ...w.lastShot };
  n.strokes = w.strokes;
  const d = n.dynamics,
    s = w.dynamics;
  d.time = s.time;
  d.gate = s.gate;
  d.plates = [...s.plates];
  d.doors = [...s.doors];
  d.planks = [...s.planks];
  d.portalCooldown = s.portalCooldown;
  d.ufo = { ...s.ufo };
  return n;
}

