for (let course = 0; course < 4; course++)
  it(`full course route ${course + 1}`, () => {
    let w = new GolfPhysics(courses[course], 0, () => 0.9);
    const shots: number[][] = [];
    for (const [tx, ty, gx = tx, gy = ty] of routes[course]) {
      for (let attempt = 0; attempt < 3; attempt++) {
        if (w.status === "won") break;
        const distance = Math.hypot(w.ball.x - tx, w.ball.y - ty);
        if (distance < 22) break;
        const angle = Math.atan2(ty - w.ball.y, tx - w.ball.x);
        let best: GolfPhysics | undefined,
          bestCost = Infinity,
          bestShot: number[] = [];
        for (const wait of course === 1
          ? [0, 0.6, 1.2, 2, 3, 4, 5, 6]
          : [0, 0.6, 1.2, 2])
          for (const da of [0, -0.03, 0.03, -0.08, 0.08, -0.18, 0.18])
            for (let power = 60; power <= 650; power += 15) {
              const trial = clone(w);
              for (let i = 0; i < wait * 240; i++) trial.tick(1 / 240);
              if (!trial.shootable) continue;
              const vx = Math.cos(angle + da) * power,
                vy = Math.sin(angle + da) * power;
              trial.shoot(vx, vy);
              for (let i = 0; i < 240 * 12; i++) {
                trial.tick(1 / 240);
                if (trial.stopped || trial.status !== "playing") break;
              }
              const cost =
                trial.status === "won"
                  ? -1e6
                  : Math.hypot(trial.ball.x - gx, trial.ball.y - gy) +
                    (trial.recoveries ? 1e5 : 0) +
                    (!trial.stopped ? 1e4 : 0);
              if (cost < bestCost) {
                bestCost = cost;
                best = trial;
                bestShot = [wait, vx, vy];
              }
              if (cost < 2) break;
            }
        if (!best || bestCost >= distance - 1) break;
        w = best;
        shots.push(bestShot);
        console.log(
          course,
          "target",
          tx,
          ty,
          "at",
          w.ball.x,
          w.ball.y,
          "stroke",
          w.strokes,
          w.status,
        );
      }
    }
    console.log("ROUTE", course, JSON.stringify(shots));
    expect(w.status).toBe("won");
  }, 120000);

