    const m = chooseEdge(d, difficulty, { seed: 82, replay: true }),
      n = chooseEdge(d, difficulty, { seed: 82, replay: true });
    expect(m.edge).toBe(n.edge);
    expect(m.nodes).toBe(n.nodes);
