it("caps procedural voices and clears them on background/disposal", () => {
  const param = () => ({
      setValueAtTime: vi.fn(),
      linearRampToValueAtTime: vi.fn(),
      exponentialRampToValueAtTime: vi.fn(),
    }),
    oscillators: any[] = [];
  class FakeAudio {
    state = "running";
    currentTime = 1;
    destination = {};
    createGain() {
      return { gain: param(), connect: vi.fn(), disconnect: vi.fn() };
    }
    createOscillator() {
      const v = {
        frequency: param(),
        connect: vi.fn(),
        disconnect: vi.fn(),
        start: vi.fn(),
        stop: vi.fn(),
        onended: null,
      };
      oscillators.push(v);
      return v;
    }
    resume() {
      return Promise.resolve();
    }
    suspend() {
      return Promise.resolve();
    }
    close() {
      return Promise.resolve();
    }
