    m.update(duration - 0.001);
    expect(m.canTap(0)).toBe(false);
    expect(swordPose(0, 1, duration - 0.001, duration).x).toBeCloseTo(end.x, 2);
    m.update(0.002);
    expect(m.canTap(0)).toBe(true);
    for (let i = 0; i <= 100; i++) {
      const age = (i / 100) * duration,
        a = swordPose(0, 1, age, duration),
