          waypoint: 0,
          delay: 0.8,
        });
        expect(Math.hypot(p.vx, p.vy)).toBeLessThanOrEqual(650.001);
        expect(p.candidates).toBeGreaterThan(0);
        expect(p.milliseconds).toBeLessThan(550);
        expect(w.shoot(p.vx, p.vy)).toBe(true);
        expect(w.strokes).toBe(1);
      }
  });
});

