import {it,expect} from 'vitest';import {LumberMatch,branches} from '../../src/games/lumberjack/Rules';import {LumberAI} from '../../src/games/lumberjack/AI';
it('Lumberjack seeded streams always leave at least one legal chopping side',()=>{for(let seed=0;seed<100;seed++){const a=branches(seed);expect(a).toEqual(branches(seed));for(let i=0;i<a.length-1;i++)expect((a[i]!==-1&&a[i+1]!==-1)||(a[i]!==1&&a[i+1]!==1)).toBe(true);}});
it('Lumberjack counts one valid chop, rejects repeats and detects branches',()=>{const m=new LumberMatch(4);expect(m.chop(0,-1)).toBe(true);expect(m.chop(0,-1)).toBeNull();m.update(.1);m.pattern[1]=-1;expect(m.chop(0,-1)).toBe(false);expect(m.players[0].alive).toBe(false);expect(m.players[0].score).toBe(1);});
it('Lumberjack runs exactly three base rounds and adds sudden death on a tie',()=>{const m=new LumberMatch();for(let i=0;i<3;i++){m.update(2);if(i<2)m.update(2);}expect(m.round).toBe(3);expect(m.phase).toBe('between');m.update(2);expect(m.round).toBe(4);m.chop(0,-1);m.update(2);expect(m.winner).toBe(1);expect(m.totals).toEqual([1,0]);});
it('Lumberjack AI uses legal chop timing, finishes a three-round match and respects pause-by-update',()=>{for(const d of ['medium','hard','impossible'] as const){const m=new LumberMatch(9),ai=new LumberAI(d,()=>.5);for(let i=0;i<10000&&!m.winner;i++){m.update(1/60);const side=ai.update(1/60,m);if(side)m.chop(1,side);}expect(m.winner).toBe(2);expect(m.round).toBe(3);expect(m.totals[1]).toBeGreaterThan(0);}});

